  const [form, setForm] = useState({});
  const [saving, setSaving] = useState(false);
  const [saveError, setSaveError] = useState('');

  const load = useCallback(() => {
    if (!id) return;
    setState((s) => Object.assign({}, s, { loading: true, error: null }));
    Promise.all([
      ctx.api.request({ url: 'customers:get', params: { filterByTk: id, fields: ['id', 'email', 'phone'].concat(PREFS.map((p) => p.flag), PREFS.map((p) => p.at)) } }),
      ctx.api.request({ url: 'communication_consent_events:list', params: { filter: { customerId: id }, sort: ['-createdAt'], pageSize: 50, appends: ['createdBy'] } }),
      ctx.api.request({ url: 'communication_suppressions:list', params: { filter: { customerId: id, active: true }, paginate: false } }),
    ]).then(([c, e, s]) => setState({ loading: false, error: null, customer: c.data.data, events: e.data.data || [], suppressions: s.data.data || [] }),
      (err) => setState({ loading: false, error: errMsg(err), customer: null, events: [], suppressions: [] }));
  }, [id]);
  useEffect(() => { load(); }, [load]);

  const latestFor = (p) => state.events.find((e) => (e.channel === p.channel || e.channel === 'all') && (e.purpose === p.purpose || e.purpose === 'all'));
  const suppressedFor = (p) => state.suppressions.find((s) => (s.channel === p.channel || s.channel === 'all') && (s.purpose === p.purpose || s.purpose === 'all'));

  const open = (pref, mode) => {
    setSaveError('');
    setForm(mode === 'grant' ? { consentSource: 'form', consentTextVersion: CONSENT_TEXT_VERSION, evidenceReference: '', notes: '' } : { consentSource: 'customer_request', notes: '' });
    setDialog({ pref, mode });
  };
  const save = () => {
    const d = dialog;
    const values = d.mode === 'withdrawAll'
      ? { customerId: id, channel: 'all', purpose: 'marketing', action: 'withdrawn', consentSource: form.consentSource, notes: form.notes || null }
      : { customerId: id, channel: d.pref.channel, purpose: d.pref.purpose, action: d.mode === 'grant' ? 'granted' : 'withdrawn', consentSource: form.consentSource,
        consentTextVersion: d.mode === 'grant' ? form.consentTextVersion : null, evidenceReference: d.mode === 'grant' ? form.evidenceReference : null, notes: form.notes || null };
    setSaving(true); setSaveError('');
    ctx.api.request({ url: 'communication_consent_events:create', method: 'post', data: values })
      .then(() => { setSaving(false); setDialog(null); load(); }, (err) => { setSaving(false); setSaveError(errMsg(err)); });
  };

  const intro = h(Typography.Paragraph, { type: 'secondary', style: { fontSize: 12, marginBottom: 8 } },
    'Promotions are marketing messages (offers, discounts, news). Reminders are service messages about the customer’s own appointments. Each box is separate: turning one on never turns on another. ',
    'Ticking a box records the customer’s consent with evidence; it is not consent by itself. SMS is stored now and will be used when SMS sending is added.');

  if (!id) {
    return h('div', { style: { minWidth: 0 } },
      h(Typography.Title, { level: 5, style: { marginTop: 4 } }, 'Communication Preferences'), intro,
      h(Alert, { type: 'info', showIcon: true, style: { marginBottom: 8 }, message: 'New customers start with every preference off.', description: 'Save the customer first, then open Edit to record consent with its evidence.' }),
      ['Email', 'SMS'].map((g, gi) => h('fieldset', { key: g, style: { border: 0, padding: 0, margin: '0 0 8px', minWidth: 0 } },
        h('legend', { style: { fontWeight: 600, fontSize: 13, marginBottom: 4 } }, g + (g === 'SMS' ? ' (future channel)' : '')),
        PREFS.slice(gi * 2, gi * 2 + 2).map((p) => h('div', { key: p.flag }, h(Checkbox, { checked: false, disabled: true }, p.label))))));
  }
  if (state.loading && !state.customer) return h('div', { style: { padding: 12 } }, h(Spin, null));
  if (state.error) return h(Alert, { type: 'error', showIcon: true, message: 'Could not load communication preferences', description: state.error, action: h(Button, { size: 'small', onClick: load }, 'Retry') });

  const c = state.customer || {};
  const usable = { email: /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(c.email || '')), sms: String(c.phone || '').replace(/\D/g, '').length >= 7 };
  const row = (p) => {
    const on = c[p.flag] === true;
    const sup = suppressedFor(p);
    const last = latestFor(p);
    const blockedGrant = !on && (!canGrant || sup || !usable[p.channel]);
    const why = !canGrant ? 'Only an Admin or Manager can record an opt-in.' : sup ? 'The customer opted out. A manager must lift the suppression, with evidence, first.' : !usable[p.channel] ? (p.channel === 'email' ? 'Add a valid email address first.' : 'Add a phone number first.') : '';
    const box = h(Checkbox, { checked: on, disabled: blockedGrant, onChange: () => open(p, on ? 'withdraw' : 'grant'), 'aria-describedby': 'bw-pref-' + p.flag }, p.label);
    return h('div', { key: p.flag, style: { padding: '6px 0', borderTop: '1px solid ' + token.colorSplit, minWidth: 0 } },
      blockedGrant && why ? h(Tooltip, { title: why }, h('span', null, box)) : box,
      h('div', { id: 'bw-pref-' + p.flag, style: { fontSize: 12, color: token.colorTextSecondary, marginLeft: 24, overflowWrap: 'anywhere' } },
        on ? h(Tag, { color: 'green', style: { marginRight: 6 } }, 'Opted in') : h(Tag, { style: { marginRight: 6 } }, 'Not opted in'),
        sup ? h(Tag, { color: 'red', style: { marginRight: 6 } }, 'Opted out') : null,
        on && c[p.at] ? 'since ' + fmt(c[p.at]) + '. ' : '',
        last ? 'Last change: ' + (last.action === 'granted' ? 'opted in' : 'opted out') + ' ' + fmt(last.recordedAt || last.createdAt) + ' · ' + (SOURCE_LABEL[last.consentSource] || last.consentSource) +
          (last.createdBy ? ' · by ' + (last.createdBy.nickname || last.createdBy.username || 'staff') : last.recordedByLabel ? ' · by ' + last.recordedByLabel : '') + (last.evidenceReference ? ' · evidence ' + last.evidenceReference : '') : 'No consent recorded yet.',
        blockedGrant && why ? h('div', null, why) : null));
  };
  const anyMarketingOn = c.emailMarketingOptIn === true || c.smsMarketingOptIn === true;

  const dlg = dialog ? h(Modal, {
    open: true, onCancel: () => setDialog(null), onOk: save, confirmLoading: saving, okText: dialog.mode === 'grant' ? 'Record opt-in' : 'Record opt-out', okButtonProps: { disabled: dialog.mode === 'grant' && !String(form.evidenceReference || '').trim() },
    title: dialog.mode === 'grant' ? 'Record consent' : dialog.mode === 'withdrawAll' ? 'Unsubscribe from all marketing' : 'Record opt-out', width: 480, destroyOnClose: true,
  },
  h(Typography.Paragraph, { style: { fontSize: 13 } }, dialog.mode === 'withdrawAll' ? 'Turns off promotions by email and SMS. Appointment reminders are not changed.' : dialog.pref.label),
  dialog.mode === 'grant' ? h(Alert, { type: 'warning', showIcon: true, style: { marginBottom: 12 }, message: 'Only record consent the customer actually gave, and keep the evidence.' }) : null,
  h('label', { style: { display: 'block', fontSize: 12, marginBottom: 4 } }, dialog.mode === 'grant' ? 'How the customer gave consent' : 'How the customer opted out'),
  h(Select, { value: form.consentSource, onChange: (v) => setForm((f) => Object.assign({}, f, { consentSource: v })), options: dialog.mode === 'grant' ? GRANT_SOURCES : OPTOUT_SOURCES, style: { width: '100%', marginBottom: 10 }, 'aria-label': 'Consent source' }),
  dialog.mode === 'grant' ? h('div', null,
    h('label', { style: { display: 'block', fontSize: 12, marginBottom: 4 } }, 'Consent wording version'),
    h(Input, { value: form.consentTextVersion, onChange: (e) => setForm((f) => Object.assign({}, f, { consentTextVersion: e.target.value })), style: { marginBottom: 10 }, 'aria-label': 'Consent wording version' }),
    h('label', { style: { display: 'block', fontSize: 12, marginBottom: 4 } }, 'Evidence reference (required)'),
    h(Input, { value: form.evidenceReference, placeholder: 'e.g. signed form #1042 or online submission id', onChange: (e) => setForm((f) => Object.assign({}, f, { evidenceReference: e.target.value })), style: { marginBottom: 10 }, 'aria-label': 'Evidence reference' })) : null,
  h('label', { style: { display: 'block', fontSize: 12, marginBottom: 4 } }, 'Notes (optional)'),
  h(Input.TextArea, { value: form.notes, rows: 2, onChange: (e) => setForm((f) => Object.assign({}, f, { notes: e.target.value })), 'aria-label': 'Notes' }),
  saveError ? h(Alert, { type: 'error', showIcon: true, style: { marginTop: 10 }, message: saveError }) : null) : null;

  return h('div', { style: { minWidth: 0 } },
    h(Typography.Title, { level: 5, style: { marginTop: 4 } }, 'Communication Preferences'), intro,
    h('fieldset', { style: { border: 0, padding: 0, margin: '0 0 10px', minWidth: 0 } }, h('legend', { style: { fontWeight: 600, fontSize: 13 } }, 'Email'), PREFS.slice(0, 2).map(row)),
    h('fieldset', { style: { border: 0, padding: 0, margin: '0 0 10px', minWidth: 0 } }, h('legend', { style: { fontWeight: 600, fontSize: 13 } }, 'SMS (future channel)'), PREFS.slice(2).map(row)),
    anyMarketingOn ? h(Button, { size: 'small', onClick: () => open(null, 'withdrawAll') }, 'Unsubscribe from all marketing') : null,
    h(Typography.Paragraph, { type: 'secondary', style: { fontSize: 12, marginTop: 8, marginBottom: 0 } }, 'Changes here are saved immediately to the consent history; the Submit button is not needed for them.'),
    dlg);
}

ctx.render(h(CommunicationPreferences));
